script:
frappe.ui.form.on("Customer Product Specification", {
 refresh(frm) {
  if (frm.is_new() || !frappe.user.has_role("Sales Master Manager")) return;
  const decide = (action) => {
   if (frm.is_dirty()) { frappe.msgprint(__("Save the specification before approving or rejecting a price.")); return; }
   const grid = frm.fields_dict.pricing && frm.fields_dict.pricing.grid;
   const selected = grid ? grid.get_selected_children() : [];
   const drafts = (frm.doc.pricing || []).filter(row => (row.approval_status || "Draft") === "Draft");
   const row = selected.length === 1 ? selected[0] : (drafts.length === 1 ? drafts[0] : null);
   if (!row) { frappe.msgprint(__("Tick one Draft price row first.")); return; }
   const approving = action === "approve";
   frappe.prompt([{fieldname:"notes",fieldtype:"Small Text",label:__("Approval Notes"),reqd:!approving}], values => frappe.call({
    method:"production_log.job_card_tracking.cps_pricing.approve_cps_price",
    args:{cps:frm.doc.name,row:row.name,action:action,notes:values.notes},
    freeze:true,freeze_message:__("Recording the decision..."),
    callback(r) { if (r.message) { frappe.show_alert({message:__("Price row is now {0}.",[r.message.approval_status]),indicator:approving?"green":"red"}); frm.reload_doc(); } }
   }), approving?__("Approve Price"):__("Reject Price"), approving?__("Approve"):__("Reject"));
  };
  frm.add_custom_button(__("Approve Price"),()=>decide("approve"),__("Pricing"));
  frm.add_custom_button(__("Reject Price"),()=>decide("reject"),__("Pricing"));
 }
});

frappe.ui.form.on("Customer Product Specification", {
    refresh(frm) {
        if (frm.doc.docstatus !== 1) return;

        frm.add_custom_button("Revise Customer Spec", () => open_revise_dialog(frm)).addClass("btn-primary");

        frm.add_custom_button("Change history", () => {
            frappe.set_route("List", "Version", {
                ref_doctype: "Customer Product Specification",
                docname: frm.doc.name,
            });
        });
    },
});

function open_revise_dialog(frm) {
    const is_cp = frm.doc.product_type === "Computer Paper";
    const rows = (frm.doc.colour_of_parts || []).map((r) => ({
        part_number: r.part_number,
        paper_type: r.paper_type,
        gsm: r.gsm,
        colour: r.colour,
    }));

    const fields = [
        {
            fieldtype: "HTML",
            fieldname: "blurb",
            options:
                '<div class="text-muted small" style="margin-bottom:8px">Revises <b>' +
                frappe.utils.escape_html(frm.doc.name) +
                '</b> in place. The spec keeps its name, job cards already raised keep the old values on their travellers, and the change is written to the Version log plus Revision Notes. Nothing is cancelled or amended.</div>',
        },
        {
            fieldtype: "Small Text",
            fieldname: "reason",
            label: "Reason for revision",
            reqd: 1,
            description: "Why is the spec changing? e.g. customer LPO ref, email, phone confirmation.",
        },
    ];

    if (is_cp) {
        fields.push({
            fieldtype: "Table",
            fieldname: "parts",
            label: "Colour of Parts",
            cannot_add_rows: true,
            cannot_delete_rows: true,
            in_place_edit: true,
            data: rows,
            get_data: () => rows,
            description:
                "Part 1 must be CB 55gsm, middle parts CFB 50gsm, last part CF 55gsm. Parts cannot be added or removed here.",
            fields: [
                { fieldname: "part_number", fieldtype: "Int", label: "Part", in_list_view: 1, read_only: 1, columns: 1 },
                { fieldname: "paper_type", fieldtype: "Select", label: "Paper", options: "CB\nCFB\nCF\n60 GSM Bond\n70 GSM Bond", in_list_view: 1, columns: 3 },
                { fieldname: "gsm", fieldtype: "Int", label: "GSM", in_list_view: 1, columns: 2 },
                { fieldname: "colour", fieldtype: "Data", label: "Colour", in_list_view: 1, reqd: 1, columns: 4 },
            ],
        });
    }

    const d = new frappe.ui.Dialog({
        title: "Revise Customer Spec",
        size: "large",
        fields: fields,
        primary_action_label: "Revise",
        primary_action(values) {
            const args = { spec: frm.doc.name, reason: (values.reason || "").trim() };
            if (is_cp) {
                const parts = (d.fields_dict.parts.get_value() || []).map((r) => ({
                    part_number: r.part_number,
                    paper_type: r.paper_type,
                    gsm: r.gsm,
                    colour: r.colour,
                }));
                args.parts = JSON.stringify(parts);
            }
            frappe.call({
                method: "cps_revise",
                args: args,
                freeze: true,
                freeze_message: "Recording revision…",
            }).then((r) => {
                const m = (r && r.message) || {};
                if (!m.ok) return;
                d.hide();
                frm.reload_doc();
                frappe.msgprint({
                    title: "Revision recorded",
                    indicator: "green",
                    message:
                        m.changes && m.changes.length
                            ? "<ul><li>" + m.changes.map(frappe.utils.escape_html).join("</li><li>") + "</li></ul>"
                            : "Note recorded; no field values changed.",
                });
            });
        },
    });
    d.show();
}
